func (catalog_uk) Locale() language.Tag { return loc_uk }

func (catalog_uk) Translator() locales.Translator { return tr_uk }

func (catalog_uk) String(tik string, args ...any) string {
	b := poolBufGet()
	defer poolBufPut(b)
	f := writers_uk[tik]
	if f == nil {
		_, _ = MissingTranslation(b, loc_uk, tik, args...)
	} else {
		_, _ = f(b, args...)
	}
	return b.String()
}

func (catalog_uk) Write(
	writer io.Writer, tik string, args ...any,
) (written int, err error) {
	f := writers_uk[tik]
	if f == nil {
		return MissingTranslation(writer, loc_uk, tik, args...)
	}
	return f(writer, args...)
}
